export const ABOUT_TEXT: string[] = ["ABOUT | LeesideTableTennis", "ABOUT LEESIDE TABLE TENNIS", "Leeside Table Tennis is a Cork City Table Tennis Club. Train from once to five times a week!", "A truly diverse club, crossing all nationalities,", "All players, all ages, all abilities welcome!", "(Closed on public holidays)", "Flexible Membership Options:", "5 sessions a week for 6 months", "1 session a week for 6 months", "Our Club Chairperson Ben is a highly experienced, qualified ITTF and ITTA coach. Ben has cached for 30+ years and has seen over 50 of his players represent Ireland.", "Head of Community & Participation Table Tennis", "Gary is a qualified and experienced School & Community Coach", "Our Junior Coach Conall is also a founding member of the current CSN Bishopstown Table Tennis team. He has represented Munster at the annual Inter-Pros in 2025 & 2026.", "A huge asset to our coaching team Jean brings a huge amount of technical knowledge and playing experience to our club.", "An experienced Senior Player Alessandra brings a wealth of knowledge to her coaching. A top national contender, Alessandra has represented Munster at the annual Inter-Pros on many occassions.", "James Kenneally Sports Hall,", "Hollyhill Lane, Gurranabraher,"];
export const ABOUT_SOURCE = "https://leesidetabletennis.wixsite.com/home/about";
export const POLICIES_TEXT: string[] = ["POLICIES | LeesideTableTennis", "Our club is managed by a Committee elected each year as part of our AGM to govern our club in line with the rules of our club constitution.", "We are affiliated with Table Tennis Ireland (TTI) and in accordance with Sport Ireland and TTI our policy and code of conduct guidelines are available below.", "Policies / Codes of Conduct", "Please find below details of the club's primary policies and codes of conduct. If you have any questions please feel free to contact us on our ABOUT page.", "The full Club Handbook is available to all members. PLease contact a committee member for acopy.", "Safeguarding and Codes of Conduct", "Leeside Table Tennis recognises that photography, video recording and livestreaming play an important role in celebrating achievements, promoting participation and showcasing table tennis and our club.", "This policy applies to all events, activities, clubs, coaches, officials, volunteers, participants, parents/guardians, spectators, and media representatives. The welfare and safeguarding of children and young people will always be the primary consideration.", "Relevant Legislation and Guidance:", "- Children First Act 2015, GDPR, Data Protection Act 2018,", "- Sport Ireland Safeguarding Guidance", "Individuals wishing to take photographs or recordings for publication, club promotion, media coverage, coaching or performance analysis must register with the Event Organiser or Referee. A register of approved photographers will be maintained. Parents/guardians taking photographs of their own child for personal use are not required to register but should respect the privacy of others.", "Use of Photography and Recording", "Photography and recording may be used for promotion, competition reports, official websites and social media, coaching, performance analysis and event broadcasting. Images should focus on participation and achievement and must not be taken in changing rooms, toilets, showers, accommodation or medical areas.", "Social Media and Publication", "Leeside Table Tennis undertake to use images responsibly, avoid unnecessary personal information and avoid linking children’s full names with images wherever possible. Coaches, officials and volunteers must not use images obtained through their role for personal purposes without authorisation.", "Livestreaming and Coaching", "Participants will be informed when official recording or livestreaming is taking place. Recordings will be securely stored and retained only as long as necessary.", "Photographs and videos may constitute personal data. Leeside Table Tennis will process and store images lawfully, fairly and securely.", "Any concerns regarding photography, filming, suspicious behaviors or misuse of images should be reported immediately to the Leeside Table Tennis Safeguarding Officer.", "Leeside Table Tennis reserves the right to:", "stop photography, remove accreditation or require individuals to leave the venue where safeguarding concerns arise.", "As a club we promise to continue to evolve both in what we teach and how we teach it. Our club is our members and we are committed to create positive feedback loops, that will drive our decisions and our club's future."];
export const POLICIES_SOURCE = "https://leesidetabletennis.wixsite.com/home/general-5";
